  Dhikr(
    id: 404,
    categoryId: 4,
    sort: 4,
    arabic: 'اللَّهُمَّ أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، اللَّهُمَّ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ',
    transliteration: '',
    translation: '',
    virtue: LText(ar: 'يقولها بعد الوضوء والاضطجاع على الشق الأيمن، ويجعلها آخر ما يتكلم به؛ فإن مات من ليلته مات على الفطرة.', en: 'يقولها بعد الوضوء والاضطجاع على الشق الأيمن، ويجعلها آخر ما يتكلم به؛ فإن مات من ليلته مات على الفطرة.'),
    source: LText(ar: 'متفق عليه · صحيح', en: 'متفق عليه · صحيح'),
    count: 1,
  ),
  Dhikr(
    id: 405,
    categoryId: 4,
    sort: 5,
    arabic: 'اللَّهُمَّ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ',
    transliteration: '',
    translation: '',
    virtue: LText(ar: 'علّمها النبي ﷺ لمن أخذ مضجعه.', en: 'علّمها النبي ﷺ لمن أخذ مضجعه.'),
